<?php
declare(strict_types=1);
require_once __DIR__.'/conexion_central.php';
final class PanelCentral {
 private static function cache(string $key,callable $loader,int $seconds=20): array{$dir=dirname(__DIR__).'/tmp/central-cache';$file=$dir.'/'.preg_replace('/[^a-z0-9_-]/i','_',$key).'.json';if(is_file($file)&&filemtime($file)>=time()-$seconds){$value=json_decode((string)file_get_contents($file),true);if(is_array($value))return $value;}$value=$loader();if(!is_dir($dir))@mkdir($dir,0775,true);if(is_dir($dir))@file_put_contents($file,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);return $value;}
 private static function invalidateCache(): void{$dir=dirname(__DIR__).'/tmp/central-cache';if(!is_dir($dir))return;foreach(glob($dir.'/*.json')?:[] as $file)@unlink($file);}
 public static function vacio(): array{return ['empresas'=>0,'empresas_activas'=>0,'aceptados'=>0,'en_proceso'=>0,'total_mes'=>0.0,'documentos_mes'=>0,'con_incidencias'=>0,'recientes'=>[]];}
 public static function resumen(): array{$pdo=ConexionCentral::conectar();$d=self::vacio();$r=$pdo->query("SELECT COUNT(*) empresas,SUM(activo=1) activas FROM empresa")->fetch();$d['empresas']=(int)$r['empresas'];$d['empresas_activas']=(int)$r['activas'];$r=$pdo->query("SELECT SUM(estado='aceptado') aceptados,SUM(estado IN ('procesando','enviado')) en_proceso,SUM(estado IN ('rechazado','error')) incidencias,SUM(IF(fecha_emision>=DATE_FORMAT(CURDATE(),'%Y-%m-01'),total,0)) total_mes,SUM(fecha_emision>=DATE_FORMAT(CURDATE(),'%Y-%m-01')) documentos_mes FROM comprobante")->fetch();foreach(['aceptados','en_proceso','incidencias','documentos_mes'] as $k){$d[$k==='incidencias'?'con_incidencias':$k]=(int)($r[$k]??0);}$d['total_mes']=(float)($r['total_mes']??0);$d['recientes']=$pdo->query("SELECT c.tipo_doc,c.serie,c.correlativo,c.cliente_razon_social,c.total,c.estado,c.fecha_creacion,e.em_razon_social,e.em_nombre_comercial FROM comprobante c INNER JOIN empresa e ON e.em_id=c.em_id ORDER BY c.fecha_creacion DESC LIMIT 7")->fetchAll();return $d;}
 public static function empresas(): array{$rows=self::cache('empresas',static fn():array=>ConexionCentral::conectar()->query("SELECT e.em_id,e.em_ruc,e.em_razon_social,e.em_nombre_comercial,e.em_direccion,e.em_ubigeo,e.em_departamento,e.em_provincia,e.em_distrito,e.em_tipo_afectacion_igv,e.em_porcentaje_igv,e.qpse_user,e.qpse_modo,e.sunat_client_id,e.sunat_sol_usuario,e.activo,e.fecha_creacion,COUNT(c.cmp_id) comprobantes,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='01' AND sd.activo=1 LIMIT 1) factura,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='03' AND sd.activo=1 LIMIT 1) boleta,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='07' AND sd.serie LIKE 'F%' AND sd.activo=1 LIMIT 1) nc_factura,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='07' AND sd.serie LIKE 'B%' AND sd.activo=1 LIMIT 1) nc_boleta,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='08' AND sd.serie LIKE 'F%' AND sd.activo=1 LIMIT 1) nd_factura,(SELECT CONCAT(sd.serie,'|',sd.correlativo) FROM serie_documento sd WHERE sd.em_id=e.em_id AND sd.tipo_doc='08' AND sd.serie LIKE 'B%' AND sd.activo=1 LIMIT 1) nd_boleta FROM empresa e LEFT JOIN comprobante c ON c.em_id=e.em_id GROUP BY e.em_id ORDER BY e.fecha_creacion DESC")->fetchAll(),3600);$locales=self::locales();foreach($rows as &$row)$row['locales']=$locales[(int)$row['em_id']]??[];return $rows;}
 public static function usuarios(): array{return self::cache('usuarios',static fn():array=>ConexionCentral::conectar()->query("SELECT usu_id,usu_usuario,usu_activo,fecha_creacion FROM usuario_intelsoft ORDER BY fecha_creacion DESC")->fetchAll(),3600);}
 public static function opcionesEmpresas(): array{return self::cache('opciones_empresas',static fn():array=>ConexionCentral::conectar()->query("SELECT em_id,em_ruc,em_razon_social,em_nombre_comercial FROM empresa ORDER BY COALESCE(NULLIF(em_nombre_comercial,''),em_razon_social)")->fetchAll(),3600);}
 public static function opcionesLocales(): array{return self::cache('opciones_locales',static fn():array=>ConexionCentral::conectar()->query("SELECT l.loc_id,l.em_id,l.loc_codigo,l.loc_nombre,e.em_razon_social,e.em_nombre_comercial FROM local_empresa l INNER JOIN empresa e ON e.em_id=l.em_id WHERE l.loc_activo=1 ORDER BY COALESCE(NULLIF(e.em_nombre_comercial,''),e.em_razon_social),l.loc_principal DESC,l.loc_nombre")->fetchAll(),3600);}
 private static function filtrosComprobantes(array $filters): array{
  $empresa=max(0,(int)($filters['empresa']??0));$local=max(0,(int)($filters['local']??0));$tipo=(string)($filters['tipo']??'');$estado=(string)($filters['estado']??'');$desde=(string)($filters['desde']??'');$hasta=(string)($filters['hasta']??'');$buscar=trim((string)($filters['buscar']??''));
  if(!in_array($tipo,['01','03','07','08','09'],true))$tipo='';if(!in_array($estado,['aceptado','procesando','enviado','rechazado','error'],true))$estado='';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$desde))$desde='';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$hasta))$hasta='';$buscar=mb_substr($buscar,0,80);
  $normalized=compact('empresa','local','tipo','estado','desde','hasta','buscar');$where=[];$params=[];
  if($empresa){$where[]='c.em_id=?';$params[]=$empresa;}if($local){$where[]='c.loc_id=?';$params[]=$local;}if($tipo!==''){$where[]='c.tipo_doc=?';$params[]=$tipo;}if($estado!==''){$where[]='c.estado=?';$params[]=$estado;}if($desde!==''){$where[]='c.fecha_emision>=?';$params[]=$desde;}if($hasta!==''){$where[]='c.fecha_emision<DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$hasta;}
  if($buscar!==''){$term='%'.$buscar.'%';$where[]="(CONCAT(c.serie,'-',LPAD(c.correlativo,8,'0')) LIKE ? OR c.cliente_razon_social LIKE ? OR c.cliente_num_doc LIKE ?)";array_push($params,$term,$term,$term);}
  return [$normalized,$where?' WHERE '.implode(' AND ',$where):'',$params];
 }
 public static function paginaComprobantes(array $filters=[],int $perPage=25,int $page=1): array{
  $perPage=in_array($perPage,[25,50,100,200],true)?$perPage:25;$page=max(1,$page);[$normalized,$where,$params]=self::filtrosComprobantes($filters);$key='comprobantes_pagina_'.sha1(json_encode([$normalized,$perPage,$page]));
  return self::cache($key,static function()use($where,$params,$perPage,$page):array{$pdo=ConexionCentral::conectar();$count=$pdo->prepare('SELECT COUNT(*) FROM comprobante c'.$where);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
   $sql="SELECT c.cmp_id,c.loc_id,c.tipo_doc,c.serie,c.correlativo,c.fecha_emision,c.cliente_num_doc,c.cliente_razon_social,c.total,c.estado,c.fecha_creacion,e.em_razon_social,e.em_nombre_comercial,l.loc_codigo,l.loc_nombre FROM comprobante c INNER JOIN empresa e ON e.em_id=c.em_id LEFT JOIN local_empresa l ON l.loc_id=c.loc_id".$where." ORDER BY c.fecha_creacion DESC LIMIT ".$perPage." OFFSET ".$offset;$query=$pdo->prepare($sql);$query->execute($params);return ['rows'=>$query->fetchAll(),'total'=>$total,'page'=>$page,'pages'=>$pages,'per_page'=>$perPage];
  },60);
 }
 public static function comprobantes(array $filters=[]): array{return self::paginaComprobantes($filters,200,1)['rows'];}
 public static function locales(): array{return self::cache('locales',static function():array{try{$rows=ConexionCentral::conectar()->query("SELECT l.*,s.ser_id,s.tipo_doc,s.serie,s.correlativo,s.activo serie_activo FROM local_empresa l LEFT JOIN serie_documento s ON s.loc_id=l.loc_id ORDER BY l.em_id,l.loc_principal DESC,l.loc_nombre,s.tipo_doc,s.serie")->fetchAll();}catch(Throwable $e){return [];} $out=[];foreach($rows as $r){$em=(int)$r['em_id'];$id=(int)$r['loc_id'];if(!isset($out[$em][$id])){$out[$em][$id]=['loc_id'=>$id,'em_id'=>$em,'codigo'=>$r['loc_codigo'],'nombre'=>$r['loc_nombre'],'direccion'=>$r['loc_direccion'],'ubigeo'=>$r['loc_ubigeo'],'departamento'=>$r['loc_departamento'],'provincia'=>$r['loc_provincia'],'distrito'=>$r['loc_distrito'],'principal'=>(int)$r['loc_principal'],'activo'=>(int)$r['loc_activo'],'series'=>[]];}if($r['ser_id']!==null)$out[$em][$id]['series'][]=['ser_id'=>(int)$r['ser_id'],'tipo_doc'=>$r['tipo_doc'],'serie'=>$r['serie'],'correlativo'=>(int)$r['correlativo'],'activo'=>(int)$r['serie_activo']];}foreach($out as &$items)$items=array_values($items);return $out;},3600);}
 public static function tipoDocumento(string $t): string{return ['01'=>'Factura','03'=>'Boleta','07'=>'Nota de crédito','08'=>'Nota de débito','09'=>'Guía de remisión'][$t]??('Documento '.$t);}
 public static function crearEmpresa(array $d): void{
  $pdo=ConexionCentral::conectar();$pdo->beginTransaction();
  try{
   $q=$pdo->prepare('INSERT INTO empresa (em_ruc,em_razon_social,em_nombre_comercial,em_direccion,em_ubigeo,em_departamento,em_provincia,em_distrito,em_tipo_afectacion_igv,em_porcentaje_igv,qpse_user,qpse_pass,qpse_modo,sunat_client_id,sunat_client_secret,sunat_sol_usuario,sunat_sol_clave,token,activo,fecha_creacion) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,NOW())');
   $q->execute([$d['ruc'],$d['razon_social'],$d['nombre_comercial'],$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito'],$d['afectacion'],$d['igv'],$d['qpse_user'],$d['qpse_pass'],$d['qpse_modo'],$d['sunat_client_id'],$d['sunat_client_secret'],$d['sunat_sol_usuario'],$d['sunat_sol_clave'],bin2hex(random_bytes(24))]);
   $id=(int)$pdo->lastInsertId();

   $local=$pdo->prepare('INSERT INTO local_empresa (em_id,loc_codigo,loc_nombre,loc_direccion,loc_ubigeo,loc_departamento,loc_provincia,loc_distrito,loc_principal,loc_activo) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, 1)');
   $local->execute([$id,'PRINCIPAL','Local principal',$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito']]);
   $localId=(int)$pdo->lastInsertId();

   $s=$pdo->prepare('INSERT INTO serie_documento (em_id,loc_id,tipo_doc,serie,correlativo,activo) VALUES (?,?,?,?,?,1)');
   foreach([['01',$d['serie_factura'],$d['corr_factura']],['03',$d['serie_boleta'],$d['corr_boleta']],['07',$d['serie_nc_factura'],$d['corr_nc_factura']],['07',$d['serie_nc_boleta'],$d['corr_nc_boleta']],['08',$d['serie_nd_factura'],$d['corr_nd_factura']],['08',$d['serie_nd_boleta'],$d['corr_nd_boleta']]] as $row){$s->execute([$id,$localId,$row[0],$row[1],$row[2]]);}

   $pdo->commit();self::invalidateCache();
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 }
 public static function existeRuc(string $ruc): bool{$q=ConexionCentral::conectar()->prepare('SELECT 1 FROM empresa WHERE em_ruc=? LIMIT 1');$q->execute([$ruc]);return (bool)$q->fetchColumn();}
 public static function existeRucOtro(string $ruc,int $id): bool{$q=ConexionCentral::conectar()->prepare('SELECT 1 FROM empresa WHERE em_ruc=? AND em_id<>? LIMIT 1');$q->execute([$ruc,$id]);return (bool)$q->fetchColumn();}
 public static function serieEnOtroLocal(int $empresaId,int $localId,string $tipo,string $serie): bool{$q=ConexionCentral::conectar()->prepare('SELECT loc_id FROM serie_documento WHERE em_id=? AND tipo_doc=? AND serie=? LIMIT 1');$q->execute([$empresaId,$tipo,$serie]);$owner=$q->fetchColumn();return $owner!==false&&(int)$owner!==$localId;}
 public static function actualizarDatosEmpresa(int $id,array $d): void{$sql='UPDATE empresa SET em_ruc=?,em_razon_social=?,em_nombre_comercial=?,em_direccion=?,em_ubigeo=?,em_departamento=?,em_provincia=?,em_distrito=?,em_tipo_afectacion_igv=?,em_porcentaje_igv=?,qpse_user=?,qpse_modo=?,sunat_client_id=?,sunat_sol_usuario=?';$values=[$d['ruc'],$d['razon_social'],$d['nombre_comercial'],$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito'],$d['afectacion'],$d['igv'],$d['qpse_user'],$d['qpse_modo'],$d['sunat_client_id'],$d['sunat_sol_usuario']];foreach(['qpse_pass','sunat_client_secret','sunat_sol_clave'] as $field){if($d[$field]!==''){$sql.=','.$field.'=?';$values[]=$d[$field];}}$sql.=' WHERE em_id=?';$values[]=$id;$q=ConexionCentral::conectar()->prepare($sql);$q->execute($values);self::invalidateCache();}
 public static function actualizarEmpresa(int $id,array $d): void{$pdo=ConexionCentral::conectar();$pdo->beginTransaction();try{$sql='UPDATE empresa SET em_ruc=?,em_razon_social=?,em_nombre_comercial=?,em_direccion=?,em_ubigeo=?,em_departamento=?,em_provincia=?,em_distrito=?,em_tipo_afectacion_igv=?,em_porcentaje_igv=?,qpse_user=?,qpse_modo=?,sunat_client_id=?,sunat_sol_usuario=?';$values=[$d['ruc'],$d['razon_social'],$d['nombre_comercial'],$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito'],$d['afectacion'],$d['igv'],$d['qpse_user'],$d['qpse_modo'],$d['sunat_client_id'],$d['sunat_sol_usuario']];foreach(['qpse_pass','sunat_client_secret','sunat_sol_clave'] as $field){if($d[$field]!==''){$sql.=','.$field.'=?';$values[]=$d[$field];}}$sql.=' WHERE em_id=?';$values[]=$id;$pdo->prepare($sql)->execute($values);$series=[['01',$d['serie_factura'],$d['corr_factura']],['03',$d['serie_boleta'],$d['corr_boleta']],['07',$d['serie_nc_factura'],$d['corr_nc_factura']],['07',$d['serie_nc_boleta'],$d['corr_nc_boleta']],['08',$d['serie_nd_factura'],$d['corr_nd_factura']],['08',$d['serie_nd_boleta'],$d['corr_nd_boleta']]];$u=$pdo->prepare('UPDATE serie_documento SET serie=?,correlativo=? WHERE em_id=? AND tipo_doc=? AND serie LIKE ?');foreach($series as $row)$u->execute([$row[1],$row[2],$id,$row[0],substr($row[1],0,1).'%']);$pdo->commit();self::invalidateCache();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public static function guardarLocal(int $localId,int $empresaId,array $d): void{$pdo=ConexionCentral::conectar();$pdo->beginTransaction();try{if($d['principal'])$pdo->prepare('UPDATE local_empresa SET loc_principal=0 WHERE em_id=?')->execute([$empresaId]);if($localId>0){$q=$pdo->prepare('UPDATE local_empresa SET loc_codigo=?,loc_nombre=?,loc_direccion=?,loc_ubigeo=?,loc_departamento=?,loc_provincia=?,loc_distrito=?,loc_principal=?,loc_activo=? WHERE loc_id=? AND em_id=?');$q->execute([$d['codigo'],$d['nombre'],$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito'],$d['principal'],$d['activo'],$localId,$empresaId]);if(!$q->rowCount()){$v=$pdo->prepare('SELECT 1 FROM local_empresa WHERE loc_id=? AND em_id=?');$v->execute([$localId,$empresaId]);if(!$v->fetchColumn())throw new RuntimeException('Local no encontrado.');}}else{$q=$pdo->prepare('INSERT INTO local_empresa (em_id,loc_codigo,loc_nombre,loc_direccion,loc_ubigeo,loc_departamento,loc_provincia,loc_distrito,loc_principal,loc_activo) VALUES (?,?,?,?,?,?,?,?,?,?)');$q->execute([$empresaId,$d['codigo'],$d['nombre'],$d['direccion'],$d['ubigeo'],$d['departamento'],$d['provincia'],$d['distrito'],$d['principal'],$d['activo']]);$localId=(int)$pdo->lastInsertId();}$series=[['01',$d['serie_factura'],$d['corr_factura']],['03',$d['serie_boleta'],$d['corr_boleta']],['07',$d['serie_nc_factura'],$d['corr_nc_factura']],['07',$d['serie_nc_boleta'],$d['corr_nc_boleta']],['08',$d['serie_nd_factura'],$d['corr_nd_factura']],['08',$d['serie_nd_boleta'],$d['corr_nd_boleta']]];$off=$pdo->prepare('UPDATE serie_documento SET activo=0 WHERE loc_id=? AND tipo_doc=? AND serie LIKE ?');$up=$pdo->prepare('INSERT INTO serie_documento (em_id,loc_id,tipo_doc,serie,correlativo,activo) VALUES (?,?,?,?,?,1) ON DUPLICATE KEY UPDATE loc_id=VALUES(loc_id),correlativo=VALUES(correlativo),activo=1');foreach($series as $s){$off->execute([$localId,$s[0],substr($s[1],0,1).'%']);$up->execute([$empresaId,$localId,$s[0],$s[1],$s[2]]);}if(!(int)$pdo->query('SELECT COUNT(*) FROM local_empresa WHERE em_id='.(int)$empresaId.' AND loc_principal=1')->fetchColumn())$pdo->prepare('UPDATE local_empresa SET loc_principal=1 WHERE loc_id=?')->execute([$localId]);$pdo->commit();self::invalidateCache();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public static function rotarToken(int $id): void{$q=ConexionCentral::conectar()->prepare('UPDATE empresa SET token=? WHERE em_id=?');$q->execute([bin2hex(random_bytes(24)),$id]);if(!$q->rowCount())throw new RuntimeException('Empresa no encontrada.');self::invalidateCache();}
 public static function crearUsuario(string $usuario,string $clave): void{$q=ConexionCentral::conectar()->prepare('INSERT INTO usuario_intelsoft (usu_usuario,usu_password_hash,usu_activo,fecha_creacion) VALUES (?, ?, 1, NOW())');$q->execute([$usuario,password_hash($clave,PASSWORD_BCRYPT)]);self::invalidateCache();}
 public static function existeUsuario(string $usuario): bool{$q=ConexionCentral::conectar()->prepare('SELECT 1 FROM usuario_intelsoft WHERE usu_usuario=? LIMIT 1');$q->execute([$usuario]);return (bool)$q->fetchColumn();}
 public static function cambiarClave(int $id,string $clave): void{$q=ConexionCentral::conectar()->prepare('UPDATE usuario_intelsoft SET usu_password_hash=? WHERE usu_id=?');$q->execute([password_hash($clave,PASSWORD_BCRYPT),$id]);if(!$q->rowCount())throw new RuntimeException('Usuario no encontrado.');self::invalidateCache();}
 public static function alternarUsuario(int $id,int $actualId): void{$pdo=ConexionCentral::conectar();$q=$pdo->prepare('SELECT usu_activo FROM usuario_intelsoft WHERE usu_id=?');$q->execute([$id]);$activo=$q->fetchColumn();if($activo===false)throw new RuntimeException('Usuario no encontrado.');if($id===$actualId&&(int)$activo===1)throw new RuntimeException('No puedes desactivar tu propia sesión.');if((int)$activo===1&&(int)$pdo->query('SELECT COUNT(*) FROM usuario_intelsoft WHERE usu_activo=1')->fetchColumn()<=1)throw new RuntimeException('No puedes desactivar el único usuario activo.');$pdo->prepare('UPDATE usuario_intelsoft SET usu_activo=? WHERE usu_id=?')->execute([(int)$activo===1?0:1,$id]);self::invalidateCache();}
}
